/* Bauntys Production Security Shield & Anti-Debugging */
(function(){
  "use strict";
  // 1. Silent Console in Production (prevents internal data/endpoint leaks)
  try {
    var noop = function(){};
    var methods = ['log', 'debug', 'info', 'warn', 'error', 'table', 'trace', 'dir', 'dirxml', 'group', 'groupEnd', 'time', 'timeEnd', 'count', 'assert'];
    for (var i = 0; i < methods.length; i++) {
      try { window.console[methods[i]] = noop; } catch(e){}
    }
  } catch(e){}

  // 2. Disable Context Menu (Right Click)
  document.addEventListener("contextmenu", function(e){
    e.preventDefault();
    return false;
  }, {capture: true, passive: false});

  // 3. Block DevTools Shortcuts (F12, Ctrl+Shift+I/J/C/K/E, Ctrl+U, Ctrl+S)
  window.addEventListener("keydown", function(e){
    if (e.keyCode === 123) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }
    if (e.ctrlKey && e.shiftKey && (e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67 || e.keyCode === 75 || e.keyCode === 69)) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }
    if (e.metaKey && e.altKey && (e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67 || e.keyCode === 85)) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }
    if (e.ctrlKey && (e.keyCode === 85 || e.keyCode === 83)) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }
  }, {capture: true, passive: false});

  // 4. Disable text selection outside input fields
  document.addEventListener("selectstart", function(e){
    var tag = e.target && e.target.tagName;
    if (tag !== "INPUT" && tag !== "TEXTAREA") {
      e.preventDefault();
      return false;
    }
  }, {capture: true, passive: false});

  // 5. Anti-Debugging timing loop (phone rotation safe, no false-positive triggers)
  var antiDebugCheck = function() {
    // False-positive screen rotation and size checks removed to ensure smooth mobile landscape video viewing
    try {
      /* debugger */
    } catch(e){}
  };
  if (typeof window !== "undefined" && !window.location.search.includes("debug=1")) {
    // Destructive DOM replacement on screen rotation/resize is permanently disabled
  }
})();

