if (r.ok && r.file.kind === "image") { files.set(r.file.fid, r.file); it.fid = r.file.fid; }
else { it.err = errText(r); const k = v.items.indexOf(it); if (k >= 0) v.items.splice(k, 1); toast(`⚠️ ${it.name}: ${it.err}`); }
