if (b.y > g.H - 70) g.finish();
g.next -= dt; if (g.next <= 0) { const gap = Math.max(160, g.gap - g.score * 2); const top = 60 + Math.random() * (g.H - 200 - gap); g.pipes.push({x: g.W + 10, top, gap, w: 70}); g.next = 1.65; }
