c.fillStyle = "#FFE14D"; c.beginPath(); c.ellipse(0, 0, 22, 19, 0, 0, 7); c.fill();
c.fillStyle = "#FFB020"; c.beginPath(); c.ellipse(-8, 3 + Math.sin(g.t * 30) * 4, 11, 7, -0.4, 0, 7); c.fill();
