if (shelfTab === "audio" && !(me.audio || []).length) shelfTab = "reading";
h += `<div class="bx-tabs">${tabs.map(([k, t]) => `<button data-sht="${k}" class="${shelfTab === k ? "on" : ""}">${t} <i>· ${shelfFilter(k).length}</i></button>`).join("")}</div>`;
