A.saveT = Date.now();
if (!inTg) return;
const secs = Math.floor(A.heard); A.heard -= secs;
api("api/books/audio", {i: A.b.i, n: A.n, t: Math.round(t), secs}).catch(() => {});
meAt = 0;
