const legend = cats.slice(0, 5).map((c) => `<div><i style="background:${c.col}"></i>${esc(c.n)}<em>${c.p}%</em></div>`).join("")
+ (cats.length > 5 ? `<div><i style="background:#9AA0B4"></i>Qolganlari<em>${100 - cats.slice(0, 5).reduce((s, c) => s + c.p, 0)}%</em></div>` : "");
