async function watch(it, part, recheck = false) {
if (busy) return;
const targetBot = botName || "BauntyCinemabot";
const uid = (inTg && tg.initDataUnsafe && tg.initDataUnsafe.user && tg.initDataUnsafe.user.id)
|| (new URLSearchParams(window.location.search).get("user_id"))
|| "";
if (!inTg && !uid) {
toast("🤖 Bot chatiga yo'naltirilmoqda…", 2200);
const directUrl = `https://t.me/${targetBot}?start=m_${it.c}`;
setTimeout(() => { window.open(directUrl, "_blank"); }, 300);
showOpenBotSheet(it, directUrl, "Web brauzerda ochilgan. Bot chatini ochib, kinoni oling:");
return;
}
setBusy(true, part);
let r;
try {
const payload = {
code: it.c,
part,
c: it.c,
p: part,
recheck,
user_id: uid ? Number(uid) : undefined
};
const res = await fetch("api/watch", {
method: "POST",
headers: {
"Content-Type": "application/json",
"X-Init-Data": (inTg && tg.initData) ? tg.initData : ""
},
body: JSON.stringify(payload)
});
r = await res.json();
} catch (e) {
r = {ok: false, error: "network"};
}
setBusy(false);
if (r.ok && r.delivered !== false) {
haptic("ok"); markSeen(it.c, part); refreshSeen(it.c);
if (it.p > 1) {
document.querySelector(`.pbtn[data-p="${part}"]`)?.classList.add("seen");
const label = `▶️ ${nextPart(it)}-qismni ko'rish`;
$("play").textContent = label; tg.MainButton.setText(label);
toast(`✅ ${part}-qism bot chatiga yuborildi!`);
} else {
toast("✅ Kino bot chatiga yuborildi!");
setTimeout(() => inTg && tg.close && tg.close(), 650);
}
return;
}
if (r.error === "need_sub") return showSub(it, part, r.channels || []);
const targetUrl = r.url || `https://t.me/${targetBot}?start=m_${it.c}`;
if (r.action === "open_bot" || r.url || r.error === "need_start") {
haptic("ok");
toast("🤖 Bot chatiga yo'naltirilmoqda…", 2200);
if (inTg && tg.openTelegramLink) {
tg.openTelegramLink(targetUrl);
} else {
window.open(targetUrl, "_blank");
}
showOpenBotSheet(it, targetUrl, "Kinoni bot chatida tomosha qilish uchun pastdagi tugmani bosing:");
return;
}
haptic("err");
const msg = {
not_found: "❌ Bu kino olib tashlangan",
rate: `⏳ Juda ko'p so'rov. ${Math.ceil((r.retry || 600) / 60)} daqiqadan keyin urinib ko'ring`,
auth: "⚠️ Sessiya eskirgan — katalogni yopib, qayta oching",
network: "📶 Internet bilan muammo. Qayta urinib ko'ring",
send_failed: "⚠️ Yuborib bo'lmadi. Bot chatini oching",
bot_not_connected: "⚠️ Botga ulanib bo'lmadi. Bot chatini oching",
busy: "⏳ Hozir juda ko'p odam kirdi — 5-10 soniyadan keyin qayta bosing"
};
const errDesc = msg[r.error] || msg.send_failed;
toast(errDesc, 3200);
showOpenBotSheet(it, targetUrl, `${errDesc}. Bot chatida to'g'ridan-to'g'ri tomosha qiling:`);
}
